import heapq
from collections import Counter

def can_form_palindrome(s):
    # Count the frequency of each character in the string
    char_count = Counter(s)
    # Check if the string can be rearranged into a palindrome
    odd_count = sum(1 for count in char_count.values() if count % 2 != 0)
    return odd_count <= 1

def min_cost_to_palindrome(N, strings):
    # Initialize a priority queue (min-heap) to store tuples of (cost, string)
    pq = []

    # Iterate over each string and its cost
    for s, c in strings:
        # Create a tuple (cost, string) and push it onto the heap
        heapq.heappush(pq, (c, s))

    # Initialize the total cost
    total_cost = 0

    # Try to form a palindrome
    while pq:
        cost, s = heapq.heappop(pq)
        # If the string can form a palindrome, add its cost to the total cost
        if can_form_palindrome(s):
            total_cost += cost
            break
        # If the string cannot form a palindrome, add its cost to the total cost and remove it from the heap
        else:
            total_cost += cost
            pq.remove((cost, s))

    # If we still cannot form a palindrome, return -1
    if not can_form_palindrome(''.join(strings)):
        return -1

    return total_cost

