def min_palindrome_cost(N, strings):
    # Read the input
    for _ in range(N):
        s, c = input().split()
        strings.append((s, int(c)))

    # Sort strings by length in descending order
    strings.sort(key=lambda x: len(x[0]), reverse=True)

    # Array to store minimum cost to form palindrome ending at index i
    dp = [float('inf')] * (2 * N + 1)
    dp[0] = 0

    # Iterate over all possible lengths of the palindrome
    for length in range(1, 2 * N + 1):
        # Iterate over all possible starting indices
        for start in range(length):
            # Iterate over all possible ending indices
            end = start + length - 1
            # Check if the current substring is a palindrome
            if strings[end][0] == strings[start][0]:
                # Update the DP value
                dp[end + 1] = min(dp[end + 1], dp[start] + strings[end][1])

    # If the last element of the dp array is infinity, it means no palindrome can be formed
    if dp[-1] == float('inf'):
        return -1
    else:
        return dp[-1]

