def min_cost_to_form_palindrome(N, strings):
    # Dictionary to store the cost of each character
    char_cost = defaultdict(int)

    # Dictionary to store the frequency of each character in each string
    char_freq = defaultdict(int)

    # Initialize the cost dictionary
    for i, (s, c) in enumerate(strings):
        for char in s:
            char_cost[char] += i * c
            char_freq[char] += 1

    # Calculate the total cost
