from functools import lru_cache

MOD = 10**9 + 7

@lru_cache(None)
def count_permutations(n, k):
    if n == 1:
        return 1 if k == 0 else 0

    total_permutations = 0
    for i in range(1, n + 1):
        # Calculate the oddness contribution of the number i
        oddness_contribution = n - i + abs(i - k)

        # If the oddness contribution is within the possible range
        if 0 <= oddness_contribution <= n * (n - 1) // 2:
            # Recursively count permutations starting with i
            total_permutations += count_permutations(n - 1, k - oddness_contribution)

    return total_permutations % MOD

