def count_permutations(n, k):
    if k > n * n:
        return 0
    if k == 0:
        return 1 if n == 1 else 0

    # Initialize the DP table
    mod = 10**9 + 7
    dp = [[0 for _ in range(k + 1)] for _ in range(n + 1)]

    # Base case: there's one way to have an oddness of 0 with a permutation of length 0
    dp[0][0] = 1

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            # If j is less than i, it means we haven't placed any element yet
            if j < i:
                dp[i][j] = 0
            else:
                # Calculate the number of ways to achieve oddness j with i elements
                dp[i][j] = sum(dp[i - 1][j - k] for k in range(1, min(i, j) + 1)) % mod

    return dp[n][k]

