@lru_cache(None)
def count_oddness(n, k):
    if k == 0:
        # Only the identity permutation has oddness 0
        return 1 if n == 1 else 0
    if k == n * (n - 1):
        # Permutations where each element is at the correct position
        return 1 if n == 1 else 0
    if n == 1:
        # Only permutation {1} has oddness 0
        return 0 if k != 0 else 1

    count = 0
    for i in range(1, n + 1):
        # Try placing i in the first position
        new_k = k - abs(i - 1)
        if new_k >= 0:
            count = (count + count_oddness(n - 1, new_k)) % MOD

    return count

