                for k in range(len(A)):
                    if (A[k] == A[i] and B[k] == B[j]) or (A[k] == B[j] and B[k] == A[i]):
                        return False

    return True

def solve(N, A, B):
    lost_indices = set()
    for i in range(N):
        if A[i] == -1 or B[i] == -1:
            lost_indices.add(i)

    # Generate all possible pairs (A_i, B_i) excluding lost indices
    for i in range(N):
        for j in range(N):
            if i in lost_indices or j in lost_indices:
                continue
            new_A = A[:]
            new_B = B[:]
            new_A[i] = A[j]
            new_B[j] = B[i]
            if is_consistent(new_A, new_B):
                return "Yes"

    return "No"

