    max_val = 2 ** M - 1

    # Create a list of all pairs (i, j) such that i XOR j = K
    pairs = []
    for i in range(max_val + 1):
        for j in range(i + 1, max_val + 1):
            if i ^ j == K:
                pairs.append((i, j))

    # If no pairs are found, it's impossible to construct the sequence
    if not pairs:
        return [-1]

    # Construct the sequence
    sequence = []
    for i in range(max_val + 1):
        for j, k in pairs:
            if i == j:
                sequence.extend([i] * 2)
            elif i == k:
                sequence.extend([i] * 2)
            else:
                # Insert zeros to create the required XOR sequence
                sequence.extend([0] * ((i ^ k) >> 1))
                sequence.append(i)
                sequence.append(i)
                sequence.extend([0] * ((k ^ i) >> 1))

    return sequence

