    xor_groups = {}

    # Iterate over all possible binary numbers from 0 to 2^M - 1
    for i in range(1 << (M + 1)):
        # Calculate the XOR of the binary representation of i
        xor_value = i ^ (i >> 1)

        # If the XOR value is not in the dictionary, add it with a list containing only i
        if xor_value not in xor_groups:
            xor_groups[xor_value] = [i]
        else:
            # Append i to the corresponding group
            xor_groups[xor_value].append(i)

    # Construct the sequence
    sequence = []
    for group in xor_groups.values():
        # If the length of the group is odd, we need to ensure the XOR is K
        if len(group) % 2 != 0:
            # Find an element in the group that contributes to the desired XOR
            for num in group:
                if num ^ K == 0:
                    sequence.append(num)
                    break
            else:
                # If no such element is found, return -1
                return [-1]
        else:
            # If the length of the group is even, add all elements to the sequence
            sequence.extend(group)

    return sequence

