def floyd_warshall(n, edges):
    # Initialize the distance matrix with infinity
    dist = [[float('inf')] * n for _ in range(n)]

    # Set the distance to 0 for the diagonal
    for i in range(n):
        dist[i][i] = 0

    # Set the distance for the edges
    for u, v, w in edges:
        dist[u - 1][v - 1] = w
        dist[v - 1][u - 1] = w

    # Apply Floyd-Warshall algorithm
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # Count the number of unreachable edges
    unreachable_edges = sum(1 for i in range(n) for j in range(n) if dist[i][j] == float('inf'))

    return unreachable_edges

