    # Build the graph
    for u, v, weight in edges:
        graph[u - 1].append((v - 1, weight))
        graph[v - 1].append((u - 1, weight))

    # Calculate shortest paths from each vertex
    all_dist = [dijkstra(graph, i) for i in range(n)]

    # Check each edge to see if it is part of any shortest path
    not_shortest_paths = 0
    for u, v, _ in edges:
        if all_dist[u - 1][v - 1] == float('inf'):
            not_shortest_paths += 1

    return not_shortest_paths

