import heapq

def dijkstra(graph, start):
    n = len(graph)
    distances = [float('inf')] * n
    distances[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_vertex = heapq.heappop(priority_queue)

        if current_distance > distances[current_vertex]:
            continue

        for neighbor, weight in graph[current_vertex].items():
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return distances

def count_non_shortest_path_edges(graph, n):
    non_shortest_path_edges = set()

    for start in range(1, n + 1):
        for end in range(1, n + 1):
            if start == end:
                continue

            distances = dijkstra(graph, start)
            if distances[end] == float('inf'):
                # If the shortest path to end is not reachable, it means there's no path from start to end
                non_shortest_path_edges.add((start, end))

    return len(non_shortest_path_edges)

