def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def extended_gcd(a, b):
    if a == 0:
        return b, 0, 1
    gcd, x1, y1 = extended_gcd(b % a, a)
    x = y1 - (b // a) * x1
    y = x1
    return gcd, x, y

def mod_inverse(a, m):
    gcd, x, y = extended_gcd(a, m)
    if gcd != 1:
        raise ValueError("Inverse doesn't exist")
    else:
        return x % m

def solve(S):
    len_S = len(S)
    MOD = 10**9 + 7

    # dp[i][j] represents the number of ways to form a number using the first i characters,
    # with the last digit being j.
    dp = [[0 for _ in range(10)] for _ in range(len_S + 1)]

    # Base case: no digits used, last digit is 0.
    dp[0][0] = 1

    # Fill the dp table
    for i in range(1, len_S + 1):
        for j in range(10):
            if S[i - 1] == '?':
                # Replace '?' with each digit (0-9) and update dp
                for k in range(10):
                    dp[i][j] = (dp[i][j] + dp[i - 1][k]) % MOD
            else:
                # Keep the current digit and move to the next character
                if int(S[i - 1]) == j:
                    dp[i][j] = (dp[i][j] + dp[i - 1][j]) % MOD

    # The answer is the sum of dp[len_S][j] for all j from 0 to 9,
    # modulo 10^9 + 7.
    answer = sum(dp[len_S]) % MOD
    return answer

