def find_induced_subgraph(N, M, edges):
    # Step 1: Convert edges into an adjacency list
    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)

    # Step 2: Find vertices with in-degree and out-degree of 1
    one_in_one_out = []
    for u in range(1, N + 1):
        in_degree = len(adj_list[u])
        out_degree = len(adj_list[u])

        if in_degree == 1 and out_degree == 1:
            one_in_one_out.append((u, in_degree, out_degree))

    # Step 3: Check if there are at least two such vertices
    if len(one_in_one_out) < 2:
        return -1

    # Step 4: Find the pair of vertices (u, v) with the same out_degree
    for i in range(len(one_in_one_out)):
        for j in range(i + 1, len(one_in_one_out)):
            if one_in_one_out[i][2] == one_in_one_out[j][2]:
                u, _, _ = one_in_one_out[i]
                v, _, _ = one_in_one_out[j]
                break

    # Step 5: Construct the induced subgraph
    subgraph = set()
    subgraph.add(u)
    subgraph.add(v)

    # Check if the subgraph is connected
    visited = set([u, v])
    queue = [u, v]
    while queue:
        node = queue.pop(0)
        for neighbor in adj_list[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)

    if len(visited) < N:
        return -1

    # Step 6: Output the subgraph
    print(len(subgraph))
    for vertex in sorted(subgraph):
