def is_cyclic(graph):
    n = len(graph)
    visited = [False] * n
    visitedTime = [-1] * n
    parent = [-1] * n

    def dfs(node, time):
        visited[node] = True
        visitedTime[node] = time
        for neighbor in graph[node]:
            if not visited[neighbor]:
                parent[neighbor] = node
                if dfs(neighbor, time + 1):
                    return True
            elif parent[node] != neighbor:
                return True
        return False

    for i in range(n):
        if not visited[i]:
            if dfs(i, 0):
                return True
    return False

def find_cycle(graph):
    n = len(graph)
    visited = [False] * n
    visitedTime = [-1] * n
    parent = [-1] * n
    cycle = []

    def dfs(node, time):
        visited[node] = True
        visitedTime[node] = time
        for neighbor in graph[node]:
            if not visited[neighbor]:
                parent[neighbor] = node
                if dfs(neighbor, time + 1):
                    return True
            elif parent[node] != neighbor:
                # Cycle found
                current = node
                while current != neighbor:
                    cycle.append(current)
                    current = parent[current]
                cycle.append(neighbor)
                cycle.append(neighbor)  # Add the entry node twice to mark it as part of the cycle
                return True
        return False

    for i in range(n):
        if not visited[i]:
            if dfs(i, 0):
                break
    else:
        return None

    # Check if the cycle forms an induced subgraph
    cycle_set = set(cycle)
    in_degree, out_degree = defaultdict(int), defaultdict(int)
    for node in cycle:
        if node in graph:
            out_degree[node] += 1
            for neighbor in graph[node]:
                in_degree[neighbor] += 1

    if all(in_degree[node] == 1 and out_degree[node] == 1 for node in cycle_set):
        return cycle
    else:
        return None

