                queue.append(v)

    # Check for a valid subgraph
    valid_subgraph = set()
    for v in topological_order:
        if adj_list[v]:
            u = next(iter(adj_list[v]))
            valid_subgraph.add(u)
            valid_subgraph.add(v)

    if not valid_subgraph:
        return -1

    # Print the result
    print(len(valid_subgraph))
    for v in sorted(valid_subgraph):
