def find_subgraph(N, M, edges):
    # Build the adjacency list representation of the graph
    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)

    # Check if the graph has an Eulerian path or cycle
    def has_eulerian_path():
        in_degree = [0] * (N + 1)
        out_degree = [0] * (N + 1)

        for u, v in edges:
            in_degree[v] += 1
            out_degree[u] += 1

        start_degree = sum(in_degree[i] - out_degree[i] for i in range(1, N + 1))
        end_degree = sum(in_degree[i] - out_degree[i] for i in range(1, N + 1))

        # Eulerian path exists if:
        # - The total in-degree equals the total out-degree
        # - Every vertex has an in-degree and out-degree of at least 1
        # - Exactly two vertices have an in-degree and out-degree of 1 more than others
        if start_degree != end_degree:
            return False
        else:
            return sum(1 for d in in_degree[1:] + out_degree[1:] if d > 1) == 2

    if not has_eulerian_path():
        print(-1)
        return

    # Find Eulerian path using Hierholzer's algorithm
    def eulerian_path():
        stack = []
        path = []
        start_vertex = next(v for v in range(1, N + 1) if in_degree[v] - out_degree[v] == 1)

        while stack or start_vertex:
            while stack or adj_list[start_vertex]:
                if adj_list[start_vertex]:
                    stack.append(start_vertex)
                    start_vertex = adj_list[start_vertex].pop()
                else:
                    path.append(start_vertex)
                    start_vertex = stack.pop()
            while stack:
                path.append(stack.pop())

        return path

    path = eulerian_path()

    # Construct the subgraph
    subgraph = path[:]
    print(len(subgraph))
    for vertex in subgraph:
        print(vertex)

