def transpose_graph(graph):
    t_graph = defaultdict(list)
    for u in graph:
        for v in graph[u]:
            t_graph[v].append(u)
    return t_graph

def has_hamiltonian_path(graph):
    n = len(graph)
    visited = [False] * (n + 1)
    queue = deque([1])

    while queue:
        u = queue.popleft()
        visited[u] = True

        for v in graph[u]:
            if not visited[v]:
                queue.append(v)

    return all(visited)

