    t_graph = transpose_graph(graph)

    if has_hamiltonian_path(t_graph):
        hamiltonian_path = []
        current = 1
        visited = set([current])

        while len(visited) < n:
            for v in graph[current]:
                if v not in visited:
                    visited.add(v)
                    hamiltonian_path.append(v)
                    current = v
                    break
            else:
                return -1

        return len(hamiltonian_path), *hamiltonian_path
    else:
        return -1

