def prime_factors(n):
    factors = {}
    # Check for number of 2s that divide n
    while n % 2 == 0:
        if 2 in factors:
            factors[2] += 1
        else:
            factors[2] = 1
        n = n // 2
    # Check for odd factors from 3 onwards
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            if i in factors:
                factors[i] += 1
            else:
                factors[i] = 1
            n = n // i
    # If n is a prime number greater than 2
    if n > 2:
        factors[n] = 1
    return factors

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return abs(a*b) // gcd(a, b)

def max_common_divisors(A, B):
    # Get prime factors of A and B
    factors_A = prime_factors(A)
    factors_B = prime_factors(B)

    # Find common prime factors
    common_factors = {}
    for factor in factors_A:
        if factor in factors_B:
            common_factors[factor] = min(factors_A[factor], factors_B[factor])

    # If there are no common factors, return 1 (A is 1)
    if not common_factors:
        return 1

    # Calculate the maximum number of divisors
    max_divisors = 1
    for count in common_factors.values():
        max_divisors *= (count + 1)

    return max_divisors

