    def detect_cycles(graph):
        in_degree = [0] * n
        queue = deque()

        # Calculate in-degrees
        for node in graph:
            for neighbor in graph[node]:
                in_degree[neighbor] += 1

        # Collect all nodes with in-degree 0
        for i in range(n):
            if in_degree[i] == 0:
                queue.append(i)

        topological_sorted_nodes = []

        while queue:
            node = queue.popleft()
            topological_sorted_nodes.append(node)

            for neighbor in graph[node]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

        # If all nodes are visited, no cycles detected
        return len(topological_sorted_nodes) == n

    # Check if the graph is acyclic
    if not detect_cycles(graph):
        return -1

    # If the graph is acyclic, return the number of edges divided by N-1
    return (n * (n - 1)) // 2

