def backtrack(graph, day, color):
    """Try to color the graph with the current color assignment."""
    if day == len(graph):
        return True

    for color_val in range(1, len(graph) + 1):
        color[day] = color_val
        if is_valid_schedule(graph, day, color):
            if backtrack(graph, day + 1, color):
                return True
        color[day] = 0
    return False

