def is_shichi_go(n):
    def prime_factors(num):
        factors = []
        for i in range(2, int(num**0.5) + 1):
            while num % i == 0:
                factors.append(i)
                num //= i
        if num > 1:
            factors.append(num)
        return factors

    factors = prime_factors(n)
    exponents = {p: factors.count(p) for p in set(factors)}

    # Check combinations of exponents that multiply to 75
    divisors = []
    for e1 in range(76):
        for e2 in range(76 - e1):
            for e3 in range(76 - e1 - e2):
                for e4 in range(76 - e1 - e2 - e3):
                    for e5 in range(76 - e1 - e2 - e3 - e4):
                        if (e1 + 1) * (e2 + 1) * (e3 + 1) * (e4 + 1) * (e5 + 1) == 75:
                            divisors.append(1)
                            for p in exponents:
                                divisors.append(exponents[p] + 1)
    return divisors

