def count_complementary_substrings(n, s):
    # Define the complements of each character
    complements = {'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C'}

    # Step 1: Create frequency map for the input string
    s_freq = {}
    for char in s:
        if char in s_freq:
            s_freq[char] += 1
        else:
            s_freq[char] = 1

    # Step 2: Check all possible substrings
    def is_complementary(sub):
        # Calculate the frequency map for the current substring
        sub_freq = {}
        for char in sub:
            if char in sub_freq:
                sub_freq[char] += 1
            else:
                sub_freq[char] = 1

        # Calculate the frequency map for the complement of the current substring
        comp_sub_freq = {}
        for char in sub:
            comp_freq[complements[char]] = comp_freq.get(complements[char], 0) + 1

        # Check if the frequency maps are identical
        return sub_freq == comp_sub_freq

    count = 0
    for i in range(n):
        for j in range(i + 1, n + 1):
            if is_complementary(s[i:j]):
                count += 1

    return count

