def count_complementary_substrings(n, s):
    def is_complementary(sub):
        complement = {'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C'}
        return ''.join(complement[c] for c in sub) == sub

    # Count occurrences of each character in the entire string
    char_count = Counter(s)

    # Initialize the result
    result = 0

    # Iterate over all possible starting points of the substring
    for start in range(n):
        complement_count = Counter()

        # Iterate over all possible ending points of the substring
        for end in range(start, n):
            sub = s[start:end+1]
            if is_complementary(sub):
                complement_count[sub] += 1
            else:
                # Check if the complement exists in the string up to this point
                if sub[::-1] in char_count:
                    # Calculate the number of positions where the substring can start
                    positions = end - start + 1
                    result += positions * (positions + 1) // 2

    return result

