import heapq

def dijkstra(graph, start):
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    pq = [(0, start)]

    while pq:
        current_distance, current_node = heapq.heappop(pq)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor))

    return distances

def max_moves(maze):
    rows, cols = len(maze), len(maze[0])
    graph = {}

    # Build the graph
    for i in range(rows):
        for j in range(cols):
            if maze[i][j] == '.':
                neighbors = []
                if i > 0 and maze[i-1][j] == '.':
                    neighbors.append(((i-1, j), 1))
                if i < rows-1 and maze[i+1][j] == '.':
                    neighbors.append(((i+1, j), 1))
                if j > 0 and maze[i][j-1] == '.':
                    neighbors.append(((i, j-1), 1))
                if j < cols-1 and maze[i][j+1] == '.':
                    neighbors.append(((i, j+1), 1))
                graph[(i, j)] = neighbors

    # Find the maximum moves
    max_moves = 0
    for start_node in graph:
        for goal_node in graph:
            if start_node != goal_node:
                distances = dijkstra(graph, start_node)
                max_moves = max(max_moves, distances[goal_node])

    return max_moves

