from collections import defaultdict, deque

def can_assign_coordinates(N, M, edges):
    # Build the adjacency list for the graph
    graph = defaultdict(list)
    for L, R, D in edges:
        graph[L].append((R, D))

    # Perform topological sort
    def topological_sort():
        in_degree = [0] * N
        queue = deque()

        # Calculate in-degrees
        for node in graph:
            for neighbor, _ in graph[node]:
                in_degree[neighbor] += 1

        # Initialize queue with nodes with zero in-degree
        for node in range(N):
            if in_degree[node] == 0:
                queue.append(node)

        sorted_order = []
        while queue:
            node = queue.popleft()
            sorted_order.append(node)

            # Decrease the in-degree of all neighbors
            for neighbor, _ in graph[node]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

        return sorted_order if len(sorted_order) == N else []

    # Perform topological sort
    top_sort = topological_sort()

    # If a topological sort is possible, print Yes
    if top_sort:
        print("Yes")
    else:
        print("No")

