def bellman_ford(n, edges):
    # Initialize distances with infinity
    dist = [float('inf')] * n
    dist[0] = 0  # Start from node 0

    # Run Bellman-Ford algorithm
    for _ in range(n - 1):
        for u, v, d in edges:
            if dist[u] + d < dist[v]:
                dist[v] = dist[u] + d

    # Check for negative cycle
    for u, v, d in edges:
        if dist[u] + d < dist[v]:
            return False

    return True

