def has_cycle(graph, visited, path, u):
    # Mark the current node as visited
    visited[u] = True
    path[u] = True

    # Recur for all the nodes adjacent to this node
    for v in graph[u]:
        # If the child is not visited, then recursively call for it
        if not visited[v]:
            if has_cycle(graph, visited, path, v):
                return True
        # If the child is visited and in the path, then there is a cycle
        elif path[v]:
            return True

    # Backtrack: remove the current node from the path
    path[u] = False
    return False

