from collections import defaultdict, deque

def detect_cycle(graph):
    # Topological sorting using Kahn's algorithm
    indegree = defaultdict(int)
    queue = deque()

    # Calculate in-degrees
    for node in graph:
        for neighbor in graph[node]:
            indegree[neighbor] += 1

    # Populate the queue with nodes with 0 in-degree
    for node in graph:
        if indegree[node] == 0:
            queue.append(node)

    # Process nodes
    cycle_size = 0
    visited = set()
    while queue:
        node = queue.popleft()
        visited.add(node)
        cycle_size += 1
        for neighbor in graph[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    return cycle_size if len(visited) == len(graph) else cycle_size

def can_assign_coordinates(n, m, edges):
