    cycle_size = detect_cycle(graph)

    # If the graph is acyclic, print Yes
    if cycle_size == 0:
        print("Yes")
    # If the graph has cycles and all cycle sizes are even, print Yes
    elif cycle_size > 0 and all(cycle_size % 2 == 0 for cycle_size in detect_cycle(graph)):
        print("Yes")
    else:
        print("No")

