def binomial(n, k):
    return sp.binomial(n, k)

def count_paths(H, W, A, B):
    # Calculate the total number of ways to move from the top-left to the bottom-right
    total_ways = binomial(H + W - 2, B - 1)

    # Calculate the number of ways to enter the forbidden area
    # Forbidden area from the bottom: H - A columns
    # Forbidden area from the left: W - B rows
    # Diagonal paths entering the forbidden area
    invalid_paths = 0

    # Iterate over the forbidden area
    for y in range(A):
        for x in range(B):
            # Calculate the number of ways to reach the forbidden cell
            # from the top-left corner
            ways_to_forbidden = binomial(x + y, x)
            invalid_paths += ways_to_forbidden

    # Calculate the number of valid paths
    valid_paths = total_ways - invalid_paths

    # Return the result modulo 10^9 + 7
    return valid_paths % (10**9 + 7)

