def solve_tree(n, edges):
    # Create an adjacency list representation of the tree
    adj_list = defaultdict(list)
    for a, b in edges:
        adj_list[a].append(b)
        adj_list[b].append(a)

    # Initialize a list to store the number of ways to write the numbers for each vertex
    ways = [0] * (n + 1)
    ways[1] = 1  # There's one way to start with number 1 on vertex 1

    # Perform the random walk to calculate the number of ways
    for k in range(1, n + 1):
        way = 1
        visited = [False] * (n + 1)
        visited[k] = True

        # Calculate the probability of moving to each neighbor
        for neighbor in adj_list[k]:
            if not visited[neighbor]:
                # Add the probability of moving to each neighbor
                way *= (n - sum(visited)) / (n - len(visited))

        # Multiply by the number of ways to write the numbers for the neighbors
        for neighbor in adj_list[k]:
            if not visited[neighbor]:
                ways[neighbor] += ways[k] * (n - sum(visited)) / (n - len(visited))

    # Take modulo 10^9 + 7
    MOD = 10**9 + 7
    ans = [ways[k] % MOD for k in range(1, n + 1)]

    return ans

