from typing import List

def build_tree(N: int, edges: List[List[int]]) -> defaultdict:
    tree = defaultdict(list)
    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)
    return tree

def dfs(node: int, parent: int, tree: defaultdict, visited: set) -> int:
    visited.add(node)
    for neighbor in tree[node]:
        if neighbor != parent and neighbor not in visited:
            dfs(neighbor, node, tree, visited)
    return len(visited) - 1

def count_hamiltonian_paths(N: int, edges: List[List[int]]) -> List[int]:
    tree = build_tree(N, edges)
    lca = []

    # Calculate Lowest Common Ancestors (LCA)
    visited = set()
    for i in range(1, N + 1):
        lca.append(dfs(i, 0, tree, visited))

    # Initialize DP table
    mod = 10**9 + 7
    dp = [[[0] * (1 << N) for _ in range(N + 1)] for _ in range(N + 1)]

    # Base case: There is one way to reach a vertex from itself
    for i in range(1, N + 1):
        dp[i][i][1 << i] = 1

    # Fill the DP table
    for vertex in range(1, N + 1):
        for parent in tree[vertex]:
            if parent != vertex:
                for mask in range(1 << N):
                    if mask & (1 << vertex) and mask & (1 << parent):
                        dp[vertex][parent][mask] = (dp[vertex][parent][mask] + dp[parent][vertex][mask ^ (1 << vertex)]) % mod

    # Calculate the number of Hamiltonian paths starting at each vertex
    result = [0] * (N + 1)
    for vertex in range(1, N + 1):
        for i in range(1, N + 1):
            if i != vertex:
                result[vertex] = (result[vertex] + dp[i][vertex][1 << vertex]) % mod

    return result

