import heapq

def can_make_choices(N, A, B, C, choices):
    # Calculate the net change required for each variable
    net_A = B - C
    net_B = A - C
    net_C = A - B

    # If any net change is negative, it's impossible
    if net_A < 0 or net_B < 0 or net_C < 0:
        return "No", []

    # Convert choices into a list of tuples (change, variable)
    choices = [(-1 if choice == 'AB' else 0, 'A') if choice == 'AB' else 
               (-1 if choice == 'AC' else 0, 'C') if choice == 'AC' else 
               (-1 if choice == 'BC' else 0, 'B') for choice in choices]

    # Initialize the min-heap
    heap = []
    # Start with the initial state (A, B, C) and add the net changes
    heapq.heappush(heap, (net_A, 'A'))
    heapq.heappush(heap, (net_B, 'B'))
    heapq.heappush(heap, (net_C, 'C'))

    # Make choices
    result = []
    for _ in range(N):
        net_change, var = heapq.heappop(heap)
        if var == 'A':
            A += 1
        elif var == 'B':
            B += 1
        else:
            C += 1
        result.append(var)

        # Update the heap with new net changes
        new_net_A = B - C
        new_net_B = A - C
        new_net_C = A - B

        if new_net_A != 0:
            heapq.heappush(heap, (new_net_A, 'A'))
        if new_net_B != 0:
            heapq.heappush(heap, (new_net_B, 'B'))
        if new_net_C != 0:
            heapq.heappush(heap, (new_net_C, 'C'))

    return "Yes", result

