def min_cost_to_transform_wall(H, W, c, A):
    # Initialize the DP table with a large value (infinity)
    dp = [[[[float('inf')] * 11 for _ in range(W)] for _ in range(H)] for _ in range(11)]

    # Base case: if A_{i,j} == -1, the cost is 0 for any sequence of digits
    for i in range(H):
        for j in range(W):
            if A[i][j] == -1:
                for k in range(11):
                    dp[k][i][j][k] = 0

    # Fill the DP table
    for i in range(H):
        for j in range(W):
            for k in range(11):
                if A[i][j] != -1:
                    digit = A[i][j]
                    for l in range(11):
                        if l != digit:
                            cost = c[digit][l] + dp[l][i][j][k]
                            if cost < dp[digit][i][j][k]:
                                dp[digit][i][j][k] = cost

    # The minimum total cost to transform the entire wall
    min_cost = float('inf')
    for k in range(11):
        cost = dp[k][H-1][W-1][k]
        if cost < min_cost:
            min_cost = cost

    return min_cost

