        i, j, cost = pq.popleft()

        # If the square is already visited, skip it
        if (i, j) in visited:
            continue

        # Mark the square as visited
        visited.add((i, j))

        # Calculate the cost to turn the digit into 1
        total_cost += cost

        # Form new digits by turning the current digit into 1
        new_digit = (A[i][j] + 1) % 10
