def dijkstra(graph, start):
    # Initialize distances and previous nodes
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    previous = {node: None for node in graph}

    # Priority queue to store (distance, node)
    pq = [(0, start)]

    while pq:
        current_distance, current_node = heapq.heappop(pq)

        # If the current distance is greater than the stored distance, skip this node
        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight

            # If this path is shorter, update the distance and previous node
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous[neighbor] = current_node
                heapq.heappush(pq, (distance, neighbor))

    return distances, previous

def min_refuels(distances, previous, start, target):
    if distances[target] == float('inf'):
        return -1  # Target is unreachable

    path = []
    current = target

    while current:
        path.append(current)
        current = previous[current]

    path.reverse()

    # Calculate total fuel required and number of refuels needed
    total_fuel = 0
    refuels = 0
    current_fuel = L

    for i in range(len(path) - 1):
        distance = graph[path[i]][path[i + 1]]
        total_fuel += distance

        # Calculate remaining fuel after traveling the current segment
        remaining_fuel = current_fuel - distance

        # If remaining fuel is less than 0, refuel
        if remaining_fuel < 0:
            refuels += abs(remaining_fuel) // L + 1
            current_fuel = L - abs(remaining_fuel) % L

    return refuels

