def bfs(start, target, graph, L):
    queue = deque([(start, 0, 0)])  # (current node, distance, number of fills)
    visited = set([start])
    while queue:
        node, dist, fills = queue.popleft()
        if node == target:
            return fills
        for neighbor, length in graph[node]:
            new_dist = dist + length
            if new_dist <= L and neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, new_dist, fills + (1 if new_dist > L else 0)))
    return -1

