import heapq

class LazyPropagation:
    def __init__(self, n):
        self.max_range = 2 * n
        self.tree = [float('inf')] * (self.max_range + 1)
        self.lazy = [float('inf')] * (self.max_range + 1)

    def push(self, idx, diff):
        if idx <= self.max_range:
            self.tree[idx] += diff
            if idx * 2 <= self.max_range:
                self.lazy[idx * 2] += diff
            if idx * 2 + 1 <= self.max_range:
                self.lazy[idx * 2 + 1] += diff

    def pull(self, idx):
        if idx <= self.max_range:
            if idx * 2 <= self.max_range:
                self.tree[idx] = min(self.tree[idx], self.tree[idx * 2])
            if idx * 2 + 1 <= self.max_range:
                self.tree[idx] = min(self.tree[idx], self.tree[idx * 2 + 1])

    def update(self, l, r, diff, idx=1, l0=0, r0=self.max_range):
        if l > r0 or r < l0:
            return
        if l0 >= l and r0 <= r:
            self.push(idx, diff)
            return
        self.pull(idx)
        m = (l0 + r0) // 2
        self.update(l, r, diff, idx * 2, l0, m)
        self.update(l, r, diff, idx * 2 + 1, m + 1, r0)
        self.tree[idx] = min(self.tree[idx * 2], self.tree[idx * 2 + 1])

    def query(self, l, r, idx=1, l0=0, r0=self.max_range):
        if l > r0 or r < l0:
            return float('inf')
        if l0 >= l and r0 <= r:
            return self.tree[idx]
        self.pull(idx)
        m = (l0 + r0) // 2
        return min(self.query(l, r, idx * 2, l0, m), self.query(l, r, idx * 2 + 1, m + 1, r0))

def shortest_path(graph, start, end, L):
    n = len(graph)
    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    pq = [(0, start)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in graph[u]:
            next_dist = dist[u] + w
            if next_dist < dist[v]:
                dist[v] = next_dist
                heapq.heappush(pq, (next_dist, v))
                # Update lazy propagation
                lazy_propagation.update(v, v, next_dist - dist[v])
    return dist[end]

