def matrix_multiply(A, B):
    n = len(A)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % MOD
    return result

def fast_matrix_power(matrix, n):
    result = [[0] * len(matrix) for _ in range(len(matrix))]
    for i in range(len(matrix)):
        result[i][i] = 1
    base = matrix
    while n > 0:
        if n % 2 == 1:
            result = matrix_multiply(result, base)
        base = matrix_multiply(base, base)
        n //= 2
    return result

def count_independent_sets(N, A, B):
    adjacency_matrix = [[0] * N for _ in range(N)]

    for i in range(N):
        for j in range(N):
            if i != j:
                if (A[i] * A[j] + B[i] * B[j]) == 0:
                    adjacency_matrix[i][j] = 1
                    adjacency_matrix[j][i] = 1

    identity_matrix = [[0] * N for _ in range(N)]
    for i in range(N):
        identity_matrix[i][i] = 1

    adj_matrix_plus_identity = matrix_multiply(adjacency_matrix, identity_matrix)

    result_matrix = fast_matrix_power(adj_matrix_plus_identity, N)

    return result_matrix[0][0]

