def count_ways(N, sardines):
    MOD = 10**9 + 7
    on_bad_terms = []
    others = []

    # Categorize sardines
    for A, B in sardines:
        if A + B == 0:
            on_bad_terms.append((A, B))
        elif A - B == 0:
            on_bad_terms.append((A, B))
        else:
            others.append((A, B))

    # Calculate the number of ways to choose subsets with sardines on bad terms
    def comb(n, k):
        if k > n:
            return 0
        if k == 0 or k == n:
            return 1
        dp = [0] * (k + 1)
        dp[0] = 1
        for i in range(1, n + 1):
            for j in range(min(i, k), 0, -1):
                dp[j] = (dp[j] + dp[j - 1]) % MOD
        return dp[k]

    ways_with_bads = 0
    for k in range(len(on_bad_terms) + 1):
        ways_with_bads = (ways_with_bads + comb(len(on_bad_terms), k)) % MOD

    # Calculate the number of ways to choose subsets without sardines on bad terms
    ways_without_bads = comb(len(others), len(on_bad_terms))

    # Total ways to choose subsets
    total_ways = (ways_with_bads + ways_without_bads) % MOD

    return total_ways

