def solve(n, A, B):
    MOD = 10**9 + 7

    # Create a graph to store bad term relationships
    graph = defaultdict(list)
    for i, (a, b) in enumerate(zip(A, B)):
        for j in range(n):
            if i != j and a * A[j] + b * B[j] == 0:
                graph[i].append(j)
                graph[j].append(i)

    # DP array to store the number of ways to choose subsets
    dp = [0] * (1 << n)
    dp[0] = 1  # There's one way to choose no sardines

    # Iterate over each sardine
    for i in range(n):
        # Create a mask to mark the current sardine
        current_mask = 1 << i
        # Iterate over all previous masks
        for mask in range(1 << n):
            # Check if the current sardine is already in the subset
            if mask & current_mask:
                continue
            # Check if any sardine on bad terms is already in the subset
            for bad_sardine in graph[i]:
                if mask & (1 << bad_sardine):
                    continue
            # Update the DP value
            dp[mask | current_mask] = (dp[mask | current_mask] + dp[mask]) % MOD

    # The answer is the sum of all valid subsets excluding the empty set
    return sum(dp[1:]) % MOD

