def count_ways(N, A, B):
    MOD = 10**9 + 7

    # Create a dictionary to store the indices of sardines on bad terms
    bad_indices = {}
    for i in range(N):
        for j in range(i + 1, N):
            if A[i] * A[j] + B[i] * B[j] == 0:
                bad_indices[i] = i
                bad_indices[j] = j

    # If no bad terms are found, the entire set is a valid subset
    if not bad_indices:
        return 2**N % MOD

    # Initialize the DP array
    dp = [0] * (N + 1)
    dp[0] = 1  # The empty set is a valid subset

    # DP transition
    for i in range(1, N + 1):
        # If the i-th sardine is bad, it cannot be included in the subset
        if i in bad_indices:
            dp[i] = dp[i - 1] % MOD
        else:
            # Both include and exclude the i-th sardine
            dp[i] = (dp[i - 1] + dp[i - 1]) % MOD

    return dp[N] % MOD

