def can_sort_permutation(P):
    N = len(P)
    if any(P[i] != i + 1 for i in range(N)):
        return -1

    operations = []
    for i in range(N - 1, 0, -1):
        if P[i] == i + 1:
            continue
        # Find the correct position for P[i]
        target = i
        while P[target] != target + 1:
            target -= 1

        # Calculate the number of operations needed to move P[i] to its correct position
        operations.append(i + 1)
        for j in range(i, target, -1):
            P[j], P[j - 1] = P[j - 1], P[j]

    return operations

