def sort_by_operations(N, P):
    inversions = count_inversions(P)
    if inversions % 2 != 0:
        return -1

    sorted_P = sorted(P)
    operations = []

    for i in range(N - 1):
        if P[i] != sorted_P[i]:
            # Find the correct position for P[i] in the sorted list
            j = sorted_P.index(P[i])
            while j != i:
                # Perform swaps to move P[i] to its correct position
                operations.append(j + 1)
                # Shift the elements to make room for P[i]
                for k in range(j, i, -1):
                    P[k], P[k - 1] = P[k - 1], P[k]
                j = sorted_P.index(P[i])

    return operations

