def can_sort_by_swaps(N, P):
    # Check if the current order is already sorted
    if P == list(range(1, N + 1)):
        return N - 1  # No swaps needed

    # Try to sort by performing the swaps in sequence
    for i in range(N - 1):
        # Check if the current order is the target order after the i-th swap
        if P[i] > P[i + 1]:
            # Swap P[i] and P[i + 1]
            P[i], P[i + 1] = P[i + 1], P[i]
            # Check if the new order is the target order
            if P == list(range(1, N + 1)):
                return i + 1  # Return the number of swaps needed

    # If no valid sequence is found, return -1
    return -1

