def dijkstra(graph, start):
    n = len(graph)
    distances = [float('inf')] * n
    distances[start] = 0
    queue = deque([start])
    parent = [-1] * n

    while queue:
        u = queue.popleft()
        for v, weight in graph[u]:
            if distances[v] > distances[u] + weight:
                distances[v] = distances[u] + weight
                parent[v] = u
                queue.append(v)

    return distances

