def topological_sort(graph):
    in_degree = [0] * (len(graph) + 1)
    queue = deque()

    # Calculate in-degrees
    for node in graph:
        for neighbor in graph[node]:
            in_degree[neighbor] += 1

    # Initialize queue with nodes having in-degree 0
    for node in range(1, len(in_degree)):
        if in_degree[node] == 0:
            queue.append(node)

    topological_order = []
    while queue:
        node = queue.popleft()
        topological_order.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    return topological_order

def assign_signposts(graph):
    n = len(graph)
    topological_order = topological_sort(graph)
    signposts = [-1] * n

    # Assign signs starting from the end of the topological order
    for room in reversed(topological_order):
        if signposts[room] == -1:
            for neighbor in graph[room]:
                if signposts[neighbor] == -1:
                    signposts[room] = neighbor
                    break

    return signposts

