import heapq

def next_snuke(n):
    digits = list(str(n))
    carry = 1
    for i in range(len(digits) - 1, -1, -1):
        if digits[i] + carry < 10:
            digits[i] += carry
            carry = 0
        else:
            digits[i] = '0'
            carry = 1
    if carry == 1:
        digits.insert(0, '1')
    return int(''.join(digits))

def find_snuke_numbers(K):
    queue = []
    heapq.heappush(queue, (1, '1'))
    snuke_numbers = []

    while queue and len(snuke_numbers) < K:
        n, digits = heapq.heappop(queue)
        snuke_numbers.append(n)

        next_n = next_snuke(n)
        next_digits = str(next_n)

        # Check if the next number is a Snuke number
        while next_n > n and all(int(next_digits[i]) >= int(digits[i]) for i in range(len(next_digits))):
            heapq.heappush(queue, (next_n, next_digits))
            next_n = next_snuke(next_n)
            next_digits = str(next_n)

    return snuke_numbers

