class SegmentTree:
    def __init__(self, n):
        self.n = n
        self.tree = [0] * (4 * n)

    def update(self, idx, val, tree, l, r):
        if l == r:
            tree[idx] = val
            return

        mid = (l + r) // 2
        if idx <= mid:
            self.update(idx, val, tree, l, mid)
        else:
            self.update(idx, val, tree, mid + 1, r)

        tree[idx] = tree[2 * idx] + tree[2 * idx + 1]

    def query(self, ql, qr, tree, l, r):
        if ql <= l and r <= qr:
            return tree[l]
        if qr < l or r < ql:
            return 0

        mid = (l + r) // 2
        left = self.query(ql, qr, tree, l, mid)
        right = self.query(ql, qr, tree, mid + 1, r)
        return left + right

