def can_fill_matrix(N: int, S: List[int], T: List[int], U: List[int], V: List[int]) -> bool:
    for i in range(N):
        if S[i] == 0:
            # Check if the bitwise AND of row i equals U[i]
            row_and = 0
            for j in range(N):
                row_and |= V[j]
            if row_and != U[i]:
                return False
        else:
            # Check if the bitwise OR of row i equals U[i]
            row_or = 0
            for j in range(N):
                row_or |= V[j]
            if row_or != U[i]:
                return False

    for j in range(N):
        if T[j] == 0:
            # Check if the bitwise AND of column j equals V[j]
            col_and = 0
            for i in range(N):
                col_and |= S[i]
            if col_and != V[j]:
                return False
        else:
            # Check if the bitwise OR of column j equals V[j]
            col_or = 0
            for i in range(N):
                col_or |= S[i]
            if col_or != V[j]:
                return False

    return True

def fill_matrix(N: int, S: List[int], T: List[int], U: List[int], V: List[int]) -> List[List[int]]:
    matrix = [[0] * N for _ in range(N)]

