        if S[i] == 0:
            # Fill row i with U[i] using bitwise AND
            for j in range(N):
                matrix[i][j] = U[i] & V[j]
        else:
            # Fill row i with U[i] using bitwise OR
            for j in range(N):
                matrix[i][j] = U[i] | V[j]

    return matrix

