def solve_harmonious_painting(H: int, W: int, N: int, a: List[int]) -> List[List[int]]:
    grid = [[0] * W for _ in range(H)]

    def backtrack(i: int) -> bool:
        if i == N:
            return True
        c = i + 1
        for j in range(H):
            for k in range(W):
                if grid[j][k] == 0:
                    if place_color(grid, j, k, c, a[i]):
                        if backtrack(i + 1):
                            return True
            if backtrack(i + 1):
                return True
        return False

    backtrack(0)
    return grid

