    def place_color(color, start_row, start_col, fill_value):
        queue = [(start_row, start_col)]
        while queue:
            row, col = queue.pop(0)
            if 0 <= row < H and 0 <= col < W and grid[row][col] == 0:
                grid[row][col] = fill_value
                queue.extend([(row + 1, col), (row - 1, col), (row, col + 1), (row, col - 1)])

