    color_index = 0
    for i in range(H):
        for j in range(W):
            if i == 0 and j == 0:
                place_color(color_index, i, j, color_index + 1)
            elif i == 0:
                place_color(color_index, i, j, color_index + j + 1)
            elif j == 0:
                place_color(color_index, i, j, color_index + i + 1)
            else:
                place_color(color_index, i, j, color_index + (i + j) + 1)
            color_index += 1
            if color_index >= N:
                break
            if a[color_index - 1] == 0:
                break

    # Fill the remaining squares with the last color
    if color_index < N:
        last_color = color_index + 1
        while a[-1] > 0:
            for i in range(H):
                for j in range(W):
                    if grid[i][j] == 0:
                        grid[i][j] = last_color
                        a[-1] -= 1
                        if a[-1] == 0:
                            break
                if a[-1] == 0:
                    break
            if a[-1] == 0:
                break

    # Output the grid
    for row in grid:
        print(' '.join(map(str, row)))

