def bipartite_coloring(graph, n):
    color = [-1] * n
    color[0] = 0  # Start with the first node as color 0

    # Try to color the graph using BFS
    queue = [0]
    while queue:
        current = queue.pop(0)
        for neighbor in graph[current]:
            if color[neighbor] == -1:
                color[neighbor] = 1 - color[current]
                queue.append(neighbor)
            elif color[neighbor] == color[current]:
                return False
    return True

