        queue = deque([(0, 0, color)])
        while queue:
            r, c, color = queue.popleft()
            grid[r][c] = color
            color_counts[color - 1] -= 1

            # Explore neighbors
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
