                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 0 and color_counts[color - 1] > 0:
                    queue.append((nr, nc, color))

    # Check if the color assignment is valid
    if not is_valid_color_assignment(grid, color_counts):
        return None

    # Convert grid to the required output format
    output = []
    for row in grid:
        output.append(' '.join(map(str, row)))
    return output

