    if grid[r][c] == color or grid[r][c] == 0:
        return True
    return False

def is_4_connected(grid, r, c, color, N):
    if not is_valid(grid, r + 1, c, color, N) and not is_valid(grid, r - 1, c, color, N) and \
       not is_valid(grid, r, c + 1, color, N) and not is_valid(grid, r, c - 1, color, N):
        return False
    return True

def place_color(grid, row, col, k, colors, N):
    if k == N:
        return True
    for color in colors:
        if grid[row][col] == 0 and is_4_connected(grid, row, col, color, N):
            grid[row][col] = color
            if place_color(grid, row, col + 1, k + 1, colors, N):
                return True
            grid[row][col] = 0
    return False

def paint_grid(H, W, N, a):
    grid = [[0] * W for _ in range(H)]
    colors = list(range(1, N + 1))

    if sum(a) != H * W:
        return "Invalid input"

    if not place_color(grid, 0, 0, 0, colors, N):
        return "No valid solution"

    for row in grid:
        print(" ".join(map(str, row)))

